import {useEffect,useLayoutEffect,useMemo,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Canvas,useFrame,useThree} from '@react-three/fiber';
import {Box3,BoxGeometry,Mesh,OrthographicCamera,Vector3} from 'three';
import {z} from 'zod';
import {AssetRegistry} from '../../../src/operations/scene/assets/registry';
import type {AssetEntity} from '../../../src/operations/scene/assets/registry';
import {bindingsFromAssetManifest} from '../../../src/operations/scene/motion/assetAdapter';
import {evaluateMotion,parseMotionContext,parseMotionEnvelopeValue} from '../../../src/operations/scene/motion/contracts';
import {recipes} from '../../../src/operations/scene/motion/testFixtures';
import {sha256} from '../../../src/operations/scene/worldContractBundle';
import {actualMeshStats,contactSurfaces,rigidClearance} from './surface';
import {woundStrip} from './forming';
import {Studio} from './lighting';
import './style.css';

const requestShape=z.object({envelope:z.unknown(),context:z.object({snapshot:z.unknown(),asset_bindings:z.array(z.unknown()),authorizations:z.array(z.unknown())})});
const dataShape=z.object({owner:z.string(),ownerPose:z.object({position:z.tuple([z.number(),z.number(),z.number()]),yaw_rad:z.number()}),winding_function:z.string(),winding_maximum:z.number().positive(),thickness_m:z.number().positive(),world:z.unknown(),frames:z.array(z.object({name:z.string(),progress:z.number(),request:requestShape})),left_child_envelope:z.unknown(),original_post_context:z.unknown(),qualification:z.string()});
type Data=z.infer<typeof dataShape>;
const query=new URLSearchParams(location.search),expected=query.get('expected-sha');
function prepare(data:Data){const original=z.object({snapshot:z.unknown(),asset_bindings:z.array(z.unknown()),authorizations:z.array(z.unknown())}).parse(data.original_post_context),old=parseMotionContext({...original,world:data.world}),left=parseMotionEnvelopeValue(data.left_child_envelope);return {data,left:evaluateMotion(left,{...old,authorizations:[left]},recipes)};}
type Prepared=ReturnType<typeof prepare>;
function selected(input:Prepared,name:string){const frame=input.data.frames.find(f=>f.name===name);if(!frame)throw new RangeError('Explicit winding frame absent');const envelope=parseMotionEnvelopeValue(frame.request.envelope),context=parseMotionContext({...frame.request.context,world:input.data.world});return {frame,envelope,pose:evaluateMotion(envelope,context,recipes)};}
type Selected=ReturnType<typeof selected>;

function Stocks({input,current}:{readonly input:Prepared;readonly current:Selected}){
 const theta=current.pose.channels.find(c=>c.function_id===input.data.winding_function)?.value;if(theta===undefined)throw new RangeError('Canonical winding channel absent');
 const shape=useMemo(()=>woundStrip(theta,1.2,input.data.thickness_m,input.data.winding_maximum),[theta,input]);
 const left=useMemo(()=>new BoxGeometry(4,input.data.thickness_m,1.2),[input]);useEffect(()=>()=>shape.geometry.dispose(),[shape]);useEffect(()=>()=>left.dispose(),[left]);
 return <>{[{pose:current.pose,geometry:shape.geometry,right:true},{pose:input.left,geometry:left,right:false}].map(stock=><group key={stock.pose.material.material_id} position={[...stock.pose.position_m]} quaternion={[...stock.pose.orientation_xyzw]}><mesh name={'winding-stock:'+stock.pose.material.material_id} userData={{windingStock:true,right:stock.right,materialId:stock.pose.material.material_id,versionId:stock.pose.material.material_version_id,targetVolumeM3:4*1.2*input.data.thickness_m}} castShadow><primitive object={stock.geometry} attach="geometry"/><meshStandardMaterial color="#8c9fa6" metalness={.8} roughness={.38}/></mesh></group>)}</>;
}

function Diagnostics({entity,input,current,angle,revision,manifestSHA}:{readonly entity:AssetEntity;readonly input:Prepared;readonly current:Selected;readonly angle:string;readonly revision:number;readonly manifestSHA:string}){
 const {camera,scene,gl,invalidate}=useThree();
 useLayoutEffect(()=>{entity.root.updateMatrixWorld(true);const box=new Box3().setFromObject(entity.root),target=box.getCenter(new Vector3());if(angle==='close'){const winding=entity.asset.moving_parts.find(p=>p.function===input.data.winding_function&&p.binding.type==='clip');if(!winding)throw new RangeError('Actual winding pivot absent');target.copy(entity.root.localToWorld(new Vector3(...winding.pivot_m)));}const offset=angle==='side'?[0,9,20]:angle==='rear'?[-15,11,-16]:angle==='close'?[3,2.5,4]:[14,11,16];camera.position.copy(target).add(new Vector3(...offset));camera.lookAt(target);if(camera instanceof OrthographicCamera)camera.zoom=angle==='close'?145:Math.min(70,750/Math.max(8,box.getSize(new Vector3()).x));camera.updateProjectionMatrix();invalidate();},[entity,input,camera,angle,revision,invalidate]);
 useFrame(()=>{if(entity.level===null)return;scene.updateMatrixWorld(true);const meshes:Mesh[]=[];scene.traverse(n=>{if(n instanceof Mesh&&n.userData.windingStock)meshes.push(n);});if(meshes.length!==2)return;
  const socket=entity.asset.sockets.find(s=>s.id===current.pose.socket_id),node=socket&&entity.nodes.get(socket.node_id);if(!socket||!node)throw new RangeError('Actual winding support absent');const point=new Vector3(...current.pose.contact_m),normal=new Vector3(...socket.normal).applyQuaternion(node.getWorldQuaternion(node.quaternion.clone()));
  const stocks=meshes.map(mesh=>{const attribute=mesh.geometry.getAttribute('position');return {...actualMeshStats(mesh),id:mesh.userData.materialId,version:mesh.userData.versionId,right:mesh.userData.right,rootUuid:mesh.parent?.uuid,uuid:mesh.uuid,targetVolumeM3:mesh.userData.targetVolumeM3,worldVertices:Array.from({length:attribute.count},(_,i)=>new Vector3().fromBufferAttribute(attribute,i).applyMatrix4(mesh.matrixWorld).toArray()),materialContact:mesh.userData.right?contactSurfaces(mesh,point,normal.clone().negate()):null,clearance:rigidClearance(entity.root,mesh)};});
  gl.domElement.dataset.windingState=JSON.stringify({owner:input.data.owner,lod:entity.level,phase:current.frame.name,manifestSHA,pose:current.pose,stocks,machineContact:contactSurfaces(entity.root,point,normal),qualification:input.data.qualification});gl.domElement.dataset.view=angle;gl.domElement.dataset.ready='true';
 });return null;
}

function Scene({registry,input,phase,lod,angle,manifestSHA}:{readonly registry:AssetRegistry;readonly input:Prepared;readonly phase:string;readonly lod:number;readonly angle:string;readonly manifestSHA:string}){
 const {gl,invalidate}=useThree(),[revision,setRevision]=useState(0),asset=registry.manifest.assets.find(a=>a.placement_ids.some(id=>id==='equipment:'+input.data.owner));if(!asset)throw new RangeError('Winding owner absent');
 const current=useMemo(()=>selected(input,phase),[input,phase]);
 const entity=useMemo(()=>{registry.beginRun(current.envelope.run_id,current.envelope.bundle_hash);return registry.entity({run_id:current.envelope.run_id,entity_type:'equipment',entity_id:input.data.owner,bundle_hash:current.envelope.bundle_hash},asset.id);},[registry,input,asset,current.envelope.run_id,current.envelope.bundle_hash]);
 useEffect(()=>{let active=true;gl.domElement.dataset.ready='false';void entity.show(lod).then(()=>{if(active){setRevision(v=>v+1);invalidate();}},(error:unknown)=>{if(active){gl.domElement.dataset.ready='error';gl.domElement.dataset.error=String(error);}});return()=>{active=false;};},[entity,lod,gl,invalidate]);
 useLayoutEffect(()=>{gl.domElement.dataset.ready='false';entity.root.position.fromArray(input.data.ownerPose.position);entity.root.quaternion.setFromAxisAngle(new Vector3(0,1,0),input.data.ownerPose.yaw_rad);entity.applyPose(current.pose);invalidate();},[entity,input,current,revision,gl,invalidate]);
 return <><primitive object={entity.root}/><Stocks input={input} current={current}/><Diagnostics entity={entity} input={input} current={current} angle={angle} revision={revision} manifestSHA={manifestSHA}/></>;
}
function App({registry,input,manifestSHA}:{readonly registry:AssetRegistry;readonly input:Prepared;readonly manifestSHA:string}){const [phase,setPhase]=useState('start'),[angle,setAngle]=useState('front'),[lod,setLod]=useState(Number(query.get('lod')??0));useEffect(()=>()=>registry.dispose(),[registry]);return <main><header><h1>{input.data.owner} · 절단 자식의 권취</h1><span>실제 절단 기록 · 합성 후속 공정 이력</span></header><p>새 권취 주기와 같은 위치의 최종 코일 인계를 검사합니다. 실제 생산 명령의 완료 기록은 별도입니다.</p><div className="toolbar">{[0,1,2].map(n=><button key={n} onClick={()=>setLod(n)}>LOD {n}</button>)}<label>권취 단계<select aria-label="권취 단계" value={phase} onChange={e=>setPhase(e.target.value)}>{input.data.frames.map(f=><option key={f.name}>{f.name}</option>)}</select></label></div><div className="viewport"><Canvas orthographic shadows frameloop="demand" dpr={1.5} camera={{position:[14,12,16],zoom:60,near:.1,far:12000}} gl={{preserveDrawingBuffer:true}}><color attach="background" args={['#e9e0cd']}/><Studio/><ambientLight intensity={.7}/><hemisphereLight args={['#fff2db','#c3ac83',1.2]}/><directionalLight position={[0,20,10]} intensity={2.4}/><Scene registry={registry} input={input} phase={phase} lod={lod} angle={angle} manifestSHA={manifestSHA}/></Canvas></div><div className="toolbar">{[['front','정면'],['side','측면'],['rear','후면'],['close','근접']].map(([key,label])=><button key={key} onClick={()=>setAngle(key??'front')}>{label}</button>)}</div></main>;}
async function start(){const root=document.getElementById('root');if(!root)throw new RangeError('Root absent');try{const text=await(await fetch('/assets/steelworks/finishing/manifest.json')).text(),manifestSHA=await sha256(new TextEncoder().encode(text));if(manifestSHA!==expected)throw new RangeError('Exact manifest SHA mismatch');const index=z.object({cases:z.array(z.object({owner:z.string(),file:z.string(),sha256:z.string()}))}).parse(await(await fetch('./postcut-data/index.json')).json()),row=index.cases.find(r=>r.owner===query.get('owner'));if(!row)throw new RangeError('Exact owner corpus absent');const raw=await(await fetch('./postcut-data/'+row.file)).text();if(await sha256(new TextEncoder().encode(raw))!==row.sha256)throw new RangeError('Exact winding corpus SHA mismatch');const data=dataShape.parse(JSON.parse(raw)),input=prepare(data),registry=new AssetRegistry(text,{origin:location.origin}),asset=registry.manifest.assets.find(a=>a.placement_ids.some(id=>id==='equipment:'+data.owner));if(!asset)throw new RangeError('Exact asset absent');const bindings=bindingsFromAssetManifest(registry.manifest,[{owner_id:data.owner,asset_id:asset.id,socket_families:Object.fromEntries(asset.sockets.map(s=>[s.id,s.forms[0]??'']))}]),context=parseMotionContext({...data.frames[0]?.request.context,world:data.world});if(JSON.stringify(bindings)!==JSON.stringify(context.asset_bindings))throw new RangeError('Actual loader binding differs from fixture');createRoot(root).render(<App registry={registry} input={input} manifestSHA={manifestSHA}/>);}catch(error){createRoot(root).render(<p role="alert">{error instanceof Error?error.message:String(error)}</p>);}}
void start();
